import zlib

NUM_PARTITIONS = 3
# (order_id, version, event) - events of one order must stay in order
events = [
    ("order-A", 1, "created"), ("order-B", 1, "created"),
    ("order-A", 2, "paid"), ("order-C", 1, "created"),
    ("order-B", 2, "paid"), ("order-A", 3, "shipped"),
]

def partition_for(key):
    # Same key always hashes to the same partition (stable hash)
    return zlib.crc32(key.encode()) % NUM_PARTITIONS

partitions = {p: [] for p in range(NUM_PARTITIONS)}
for key, version, name in events:
    partitions[partition_for(key)].append((key, version, name))

for p, log in partitions.items():
    print("partition", p, "->", log)

# Consumer side: per-order version check rejects stale or duplicate events
last_version = {}
replayed = [("order-A", 2, "paid"), ("order-A", 1, "created"), ("order-A", 3, "shipped")]
for key, version, name in replayed:
    if version <= last_version.get(key, 0):
        print("reject stale", key, version, name)
    else:
        last_version[key] = version
        print("apply", key, version, name)

# Retry with exponential backoff, then DLQ. No real sleeping: we print the delay.
class Transient(Exception): pass
class Permanent(Exception): pass

calls = {}
def handler(msg):
    calls[msg] = calls.get(msg, 0) + 1
    if msg == "m2" and calls[msg] < 3:
        raise Transient("timeout")       # succeeds on the 3rd try
    if msg == "m3":
        raise Permanent("bad payload")   # will never succeed
    return "ok"

dlq = []
MAX_ATTEMPTS = 4
for msg in ["m1", "m2", "m3"]:
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            print(msg, "attempt", attempt, handler(msg))
            break
        except Permanent as e:
            # Permanent errors skip retries and go straight to the DLQ
            dlq.append((msg, str(e), attempt))
            print(msg, "permanent ->", "DLQ")
            break
        except Transient as e:
            delay = 2 ** (attempt - 1)   # 1s, 2s, 4s (add jitter in real code)
            print(msg, "attempt", attempt, "failed:", e, "- retry in", delay, "s")
    else:
        dlq.append((msg, "retries exhausted", MAX_ATTEMPTS))
print("DLQ:", dlq)

# Saga: run local steps; on failure run compensations in reverse order.
log = []

def make(name, fail=False):
    def do():
        if fail:
            print(name, "FAILED")
            return False
        print(name, "done")
        return True
    return do

def undo(name):
    def comp():
        print("  compensate:", name)   # must be idempotent in real systems
        log.append(name)
    return comp

steps = [
    ("reserve stock", make("reserve stock"), undo("release stock")),
    ("authorise card", make("authorise card"), undo("void authorisation")),
    ("create shipment", make("create shipment", fail=True), undo("cancel shipment")),
]

completed = []
ok = True
for name, action, compensation in steps:
    if action():
        completed.append(compensation)
    else:
        ok = False
        break

if not ok:
    print("rolling back", len(completed), "completed steps")
    for compensation in reversed(completed):   # newest first
        compensation()
print("saga result:", "success" if ok else "compensated", log)

# Idempotent producer: the broker remembers the last sequence number per (producer, partition).
class Broker:
    def __init__(self):
        self.log = []
        self.last_seq = {}   # producer id -> last accepted sequence

    def append(self, pid, seq, value):
        last = self.last_seq.get(pid, -1)
        if seq <= last:
            return "duplicate (ignored)"      # a retry of an accepted batch
        if seq > last + 1:
            return "out of order (rejected)"  # a gap means something was lost
        self.log.append(value)
        self.last_seq[pid] = seq
        return "appended"

broker = Broker()
sends = [(7, 0, "a"), (7, 1, "b"), (7, 1, "b"), (7, 3, "d"), (7, 2, "c")]
for pid, seq, value in sends:
    print("producer", pid, "seq", seq, value, "->", broker.append(pid, seq, value))
print("log:", broker.log)   # ['a', 'b', 'c'] with no duplicates
